}

/** A modified colour in both the forms the IR needs. */
interface ResolvedColor {
  /** The fully-flattened literal. */
  flat: string;
  /** The same colour with its `var()` origin preserved; equals `flat` when there was none. */
  expr: string;
}

function toToken(name: string, value: string, flatValue?: string): Token {
  // An expression whose origin is a themed var() collapses to one branch, so `themed` has to come
  // from the flattened pair instead of the value's own shape.
  return defineToken({
    name,
    value,
    ...(flatValue === undefined ? {} : { flatValue, themed: flatValue.startsWith("light-dark(") }),
  });
}

function candidates(prefix: string, root: unknown): Candidate[] {
  return collectLeaves(root).map((light) => ({ name: varName(prefix, light.path), light }));
}

function semanticColorCandidates(group: any, spec: { light: string; dark?: string }): Candidate[] {
  const darkByPath = new Map<string, Leaf>();
  if (spec.dark) {
    for (const leaf of collectLeaves(group?.semantic?.color?.[spec.dark]?.semantic)) {
      darkByPath.set(leaf.path.join("."), leaf);
    }
  }
  return collectLeaves(group?.semantic?.color?.[spec.light]?.semantic).map((light) => ({
    name: varName("", light.path),
    light,
    dark: darkByPath.get(light.path.join(".")),
  }));

