import { defineComponent, type Definition } from "../../lib/define.ts";
import { SENTINEL } from "../../lib/sentinel.ts";
import { alert as alertRaw } from "../../generated/component-styles.ts";

/** The `alert` component record: an inline message with a coloured status bar and a masked status glyph from the shared icon set. */
export const alert: Definition = defineComponent({
  name: "alert",
  css: (p) => alertRaw.replaceAll(SENTINEL, p),
});
/** Standalone `alert` stylesheet — the prefixed CSS for the status message, ready to ship as a `.css` file. */
export const alertCss: Definition["css"] = alert.css;

import { expect, test } from "vite-plus/test";
import { alertCss } from "../../src/index.ts";
import { alert } from "../../src/components/alert/index.ts";
import { validate } from "../_validate.ts";

test("alert: emits exactly one well-formed cssdoc record with no token drift", () => {
  validate(alert);
});

test("alert supports token-backed floating and inline status treatments", () => {
  const css = alertCss({ prefix: "instui" });
  expect(css).toContain("&:is(.-variant-success, .-color-success)");
  expect(css).toContain("&:is(.-variant-warning, .-color-warning)");
  expect(css).toContain("&:is(.-variant-error, .-color-danger, .-color-error)");
  for (const status of ["info", "success", "warning", "danger"]) {
    expect(css).toContain(`--instui-component-alert-${status}-background`);
    expect(css).toContain(`--instui-component-alert-${status}-background-inline`);
    expect(css).toContain(`--instui-component-alert-${status}-border-color`);
    expect(css).toContain(`--instui-component-alert-${status}-border-color-inline`);
  }
  expect(css).toContain("--instui-color-drop-shadow-shadow-color1");
  expect(css).toContain("--instui-drop-shadow-y-elevation4-dropshadow1");
  expect(css).toContain("--instui-component-text-base-on-color");
  expect(css).toContain("--pantoken-alert-icon-color");
  expect(css).toContain("&::after");
  expect(css).toContain("--instui-component-alert-icon-padding-left");
  expect(css).toContain("+ 0.75rem");
  expect(css).toContain("--instui-component-alert-icon-padding-vertical");
  expect(css).toContain("border-color: var(--instui-component-alert-info-border-color-inline)");
  expect(css).not.toContain("color-mix(");
  expect(css).toMatch(/&:is\(\s*\[class\^="-icon-"\],\s*\[class\*=" -icon-"\]/u);
  expect(css).toContain("content: none");
  // No icon/content wrapper classes anymore.
  expect(css).not.toContain(".instui-alert__icon");
  expect(css).not.toContain(".instui-alert__content");
  // Inline is a complete treatment; old no-shadow spellings remain functional aliases.
  expect(css).toMatch(
    /&:is\(\.-has-shadow-false,\s*\.-without-shadow\)\s*\{\s*box-shadow:\s*none/u,
  );
  expect(css).toMatch(/&\.-inline\s*\{[\s\S]*box-shadow:\s*none/u);
  expect(css).toContain("box-shadow: none");
  // A direct singleton and a two-button group form action rows. Unmodified actions become
  // primary or secondary by position; authored button modifiers opt out.
  expect(css).toContain("inline-size: fit-content");
  expect(css).toMatch(/&\s*>\s*\.button-group/u);
  expect(css).toContain("display: flex");
  expect(css).toContain("--instui-component-shared-tokens-spacing-general-space-md");
  expect(css).toContain("--instui-component-shared-tokens-spacing-gap-buttons");
  expect(css).toContain(".button-group > .instui-button");
  expect(css).toContain("--instui-component-base-button-small-height");
  expect(css).toContain("--instui-component-base-button-primary-inverse-hover-background");
  expect(css).toContain("--instui-component-base-button-secondary-on-color-disabled-border-color");
  expect(css).toContain("--instui-component-base-button-tertiary-hover-border-color");
  expect(css).toMatch(
    /&:is\(\.-inline,\s*\.-variant-warning,\s*\.-color-warning\)\s*>\s*\.instui-button/u,
  );
  expect(css).toContain("&.-screen-reader-only");
  expect(css).toMatch(/>\s*\.instui-close-button:not\(\[class\*="-size-"\]\)/u);
  expect(css).toContain("var(--instui-component-base-button-small-height)");
  expect(css).toContain("&:has(> .instui-close-button)");
  // Timeout mirrors InstUI milliseconds and defaults to a fade unless explicitly disabled.
  expect(css).toContain("@property --timeout");
  expect(css).toContain('syntax: "<integer>"');
  expect(css).toContain("--timeout: 0");
  expect(css).not.toContain(".instui-alert.-removing");
  expect(css).not.toContain("transition: opacity");
});

/**
 * @component pill
 * @selector .pfx-pill
 * @a11y The status colors are visual only, so state the status in the label text or a visually hidden label. The leading glyph is a masked `::before` and isn't announced.
 * @summary A compact status label; add a leading glyph with the shared `-icon-<name>` form.
 * @remarks Unlike `badge`, which shows a count, or `tag`, which is removable, the pill is a static status label; its leading glyph is a masked `::before`, not an `<img>`. Let groups wrap with `flex-wrap: wrap` on their container so compact labels reflow on narrow screens.
 * @modifier -size-x-small — The smallest pill size.
 * @modifier -size-medium — The medium pill size.
 * @modifier -size-large — The largest pill size.
 * @modifier -color-neutral — A neutral status.
 * @modifier -color-info — Informational status.
 * @modifier -color-success — Positive status.
 * @modifier -color-warning — Cautionary status.
 * @modifier -color-danger — Error status.
 * @modifier -color-plum — Plum accent status.
 * @modifier -color-aurora — Aurora accent status.
 * @modifier -color-sky — Sky accent status.
 * @modifier -color-orange — Orange accent status.
 * @modifier -color-violet — Violet accent status.
 * @modifier -color-sea — Sea accent status.
 * @modifier -color-stone — Stone accent status.
 * @modifier -icon-* — A leading glyph from the icon set (e.g. `-icon-check`), painted before the label.
 * @pseudo ::before — The leading icon glyph, sized and spaced to the pill.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-view --display-flex --gap-md" style="flex-wrap: wrap">
 *   <span class="instui-pill -color-success -icon-check">Published</span>
 *   <span class="instui-pill">Draft</span>
 *   <span class="instui-pill -color-info">In review</span>
 *   <span class="instui-pill -color-warning">Stale</span>
 *   <span class="instui-pill -color-danger">Blocked</span>
 *   <span class="instui-pill -color-violet">Pastel</span>
 * </div>
 * ```
 * @related badge — A badge is the count or notification counterpart.
 * @related tag — A tag is the removable, form-oriented counterpart.
 * @example -automatica11y
 * ```html
 * <div><span class="pfx-pill -color-neutral -size-x-small -icon-check">Draft checked</span></div>
 * <div><span class="pfx-pill -color-info -size-medium -icon-check">Review checked</span></div>
 * <div><span class="pfx-pill -color-success -size-large -icon-check">Published</span></div>
 * <div><span class="pfx-pill -color-warning">Needs review</span></div>
 * <div><span class="pfx-pill -color-danger">Blocked</span></div>
 * <div><span class="pfx-pill -color-plum">Plum team</span></div>
 * <div><span class="pfx-pill -color-aurora">Aurora team</span></div>
 * <div><span class="pfx-pill -color-sky">Sky team</span></div>
 * <div><span class="pfx-pill -color-orange">Orange team</span></div>
 * <div><span class="pfx-pill -color-violet">Violet team</span></div>
 * <div><span class="pfx-pill -color-sea">Sea team</span></div>
 * <div><span class="pfx-pill -color-stone">Stone team</span></div>
 * ```
 */
@scope (.pfx-pill) {
  & {
    display: inline-flex;
    align-items: center;
    height: var(--instui-component-pill-height);
    max-width: var(--instui-component-pill-max-width);
    padding-block: var(--instui-component-pill-padding-vertical);
    padding-inline: var(--instui-component-pill-padding-horizontal);
    gap: var(--instui-component-pill-gap-content);
    background: var(--instui-component-pill-neutral-background-color);
    color: var(--instui-component-pill-base-text-color);
    border: var(--instui-component-pill-border-width) var(--instui-component-pill-border-style)
      var(--instui-component-pill-base-border-color);
    border-radius: var(--instui-component-pill-border-radius);
    font-family: var(--instui-component-pill-font-family);
    font-size: var(--instui-component-pill-text-font-size);
