 * <nav class="pfx-global-nav-bar -minimized" aria-label="Minimized primary">
 *   <a class="item -selected" href="#home" aria-current="page" aria-label="Home"><span class="-icon-house" aria-hidden="true"></span><span class="label">Home</span></a>
 *   <a class="item" href="#inbox" aria-label="Inbox"><span class="-icon-inbox" aria-hidden="true"></span><span class="label">Inbox</span></a>
 * </nav>
 * ```
 */
@scope (.pfx-global-nav-bar) {
  & {
    display: flex;
    flex-direction: column;
    gap: var(--instui-component-side-nav-bar-content-gap);
    padding: var(--instui-component-side-nav-bar-content-margin);
    box-sizing: border-box;
    inline-size: fit-content;
    /* The rail sits on the page and runs full height (InstUI GlobalNavBar is 100% of its layout column). */
    block-size: 100%;
    min-block-size: 100%;
    background: var(--instui-component-side-nav-bar-background-color);
    color: var(--instui-component-side-nav-bar-font-color);
    font-family: var(--instui-component-side-nav-bar-item-font-family);
  }

  /* minimized: a narrow rail — the icons stay, the labels are hidden. */
  &.-minimized {
    inline-size: var(--instui-component-side-nav-bar-minimized-width);
  }

  &.-minimized .item .label {
    display: none;
  }
}

